import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { sessionStorageAdapter } from './sessionStorage';

// Read from env only - no committed key fallback. The anon key is public-safe,
// but sourcing it from VITE_* env means rotation never requires a code change
// and the project ref/key aren't baked into git history. Missing config fails
// loudly here instead of silently pointing at a hardcoded project.
const SUPABASE_URL = import.meta.env?.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env?.VITE_SUPABASE_ANON_KEY;

if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
  throw new Error(
    "Missing VITE_SUPABASE_URL or VITE_SUPABASE_ANON_KEY. Set them in your environment (.env locally, project env vars in CI/Vercel).",
  );
}

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    // localStorage on web; Keychain-backed on native iOS (see sessionStorage.ts).
    storage: sessionStorageAdapter,
    persistSession: true,
    autoRefreshToken: true,
  }
});